10: const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
11: function avatarUrl(c){return `https://images.unsplash.com/${c.photo}?auto=format&fit=crop&w=320&h=320&q=85`}
12: function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
13: function setView(view){currentView=view;$('#discoverView').classList.toggle('hidden',view!=='discover');$('#chatView').classList.toggle('hidden',view!=='chat');$('#galleryView').classList.toggle('hidden',view!=='gallery');$('#topTitle').textContent=view==='discover'?'DISCOVER':view==='chat'?activeChar?.name.toUpperCase():'KEEPSAKES';$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===(view==='gallery'?'gallery':view==='chat'?'chats':view)));if(view==='gallery')renderGallery();if(view==='discover')renderRecent();}
14: function renderCards(){const grid=$('#characterGrid');let list=characters.filter(c=>activeFilter==='All'||c.genre===activeFilter||c.tags.includes(activeFilter));grid.innerHTML=list.map(c=>`<article class="character-card" data-id="${c.id}" tabindex="0" role="button" aria-label="Start a story with ${c.name}"><div class="card-art" style="background-image:linear-gradient(0deg,#17151d 0%,transparent 60%),url('${avatarUrl(c)}'),${c.tint};background-position:center 36%;background-size:cover"><div class="art-shade" style="background:${c.tint}"></div><span class="card-tag">${c.genre.toUpperCase()}</span><button class="card-heart ${save.favorites.includes(c.id)?'saved':''}" data-fav="${c.id}" aria-label="Favorite ${c.name}">${save.favorites.includes(c.id)?'♥':'♡'}</button></div><div class="card-content"><div class="card-title-row"><h3>${c.name}</h3><span class="age">${c.age}</span></div><div class="card-blurb">${c.blurb}</div><div class="card-bottom"><div class="card-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><span class="start-link">Meet them <span>→</span></span></div></div></article>`).join('');grid.querySelectorAll('.character-card').forEach(card=>{card.addEventListener('click',e=>{if(e.target.closest('[data-fav]'))return;startChat(card.dataset.id)});card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();startChat(card.dataset.id)}})});grid.querySelectorAll('[data-fav]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const id=btn.dataset.fav;save.favorites=save.favorites.includes(id)?save.favorites.filter(x=>x!==id):[...save.favorites,id];persist();renderCards()}))}
15: function renderRecent(){const list=$('#recentList'),seen=Object.keys(save.threads);list.innerHTML=seen.map(id=>{const c=characters.find(x=>x.id===id);if(!c)return'';return`<button class="recent-story" data-open="${id}"><span class="mini-avatar" style="background-image:url('${avatarUrl(c)}')"></span><span>${c.name}</span></button>`}).join('');list.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>startChat(b.dataset.open))}
16: function threadFor(c){if(!save.threads[c.id])save.threads[c.id]={messages:[],bond:0,turn:0,started:false};return save.threads[c.id]}
17: function startChat(id){activeChar=characters.find(c=>c.id===id);const t=threadFor(activeChar);if(!t.started){t.started=true;t.messages.push({from:'bot',text:activeChar.intro,time:stamp()});persist()}$('#chatAvatar').style.backgroundImage=`url('${avatarUrl(activeChar)}')`,$('#chatName').textContent=activeChar.name,$('#typingName').textContent=activeChar.name.split(' ')[0];$('#storyIntro').innerHTML=`<span class="intro-kicker">✦ ${activeChar.role.toUpperCase()} · YOUR STORY BEGINS</span>${activeChar.place} · Every choice is yours to make.`;setView('chat');renderChat();$('#messageInput').focus()}
18: function stamp(){return new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit'}).format(new Date())}
