20: function renderChat(){const t=threadFor(activeChar);$('#messageList').innerHTML=t.messages.map(m=>`<div class="message ${m.from==='user'?'user':''}">${m.from==='bot'?`<div class="message-avatar" style="background-image:url('${avatarUrl(activeChar)}')"></div>`:''}<div class="bubble-wrap">${m.from==='bot'?`<div class="bubble-name">${activeChar.name.split(' ')[0]}</div>`:''}<div class="bubble">${escapeHtml(m.text)}</div><div class="message-time">${m.time||''}</div></div>${m.from==='user'?'<div class="message-avatar" style="display:grid;place-items:center;background:linear-gradient(135deg,#81586c,#ca8e9b);font-size:10px">J</div>':''}</div>`).join('');const suggestions=activeChar.choices[0];$('#suggestions').innerHTML=suggestions.map(s=>`<button class="suggestion">${s}</button>`).join('');$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>send(b.textContent));const bond=t.bond;$('#progressFill').style.width=`${Math.min(100,Math.max(7,bond))}%`;$('#bondLabel').textContent=bond<20?'A NEW SPARK':bond<45?'GETTING CLOSER':bond<70?'SOMETHING REAL':bond<100?'HEARTS IN SYNC':'YOUR STORY, ALWAYS';$('#chapterLabel').textContent=`CHAPTER ${String(Math.floor(t.turn/4)+1).padStart(2,'0')}`;$('#chatScroll').scrollTop=$('#chatScroll').scrollHeight;renderRecent()}
21: function escapeHtml(text){return text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
22: function makeReply(input,t){const turn=t.turn;const first=activeChar.responses[Math.min(3,Math.floor(turn/2))];const clean=input.toLowerCase();let lead='';if(/miss|like you|feel|heart|love|stay|together|beautiful|special/.test(clean))lead=['Something in their expression softens. ','The words linger between you, and they smile. ','Their eyes meet yours, open and unguarded. '][turn%3];else if(/why|how|tell me|what|story|compass|star|book/.test(clean))lead=['They consider your question, then let you in. ','A thoughtful smile crosses their face. ','They settle beside you, happy to explain. '][turn%3];else lead=['A quiet laugh slips out before they can stop it. ','They take a moment, clearly choosing their words. ','Their shoulders relax as the conversation finds its rhythm. '][turn%3];return lead+first}
23: function send(raw){const text=raw.trim();if(!text||!activeChar)return;$('#messageInput').value='';$('#messageInput').style.height='auto';addMessage('user',text);const t=threadFor(activeChar);t.turn++;t.bond=Math.min(100,t.bond+7+Math.floor(Math.random()*4));persist();$('#typing').classList.remove('hidden');$('#sendMessage').disabled=true;const reply=makeReply(text,t);setTimeout(()=>{$('#typing').classList.add('hidden');$('#sendMessage').disabled=false;addMessage('bot',reply);if(t.bond>=70&&!t.milestone){t.milestone=true;persist();showToast('A new chapter is opening between you ✦')}else if(t.bond===100)showToast('A story with no ending. Keep making moments ✦')},850)}
24: function renderGallery(){const items=save.keepsakes;const grid=$('#galleryGrid');if(!items.length){grid.innerHTML='<div class="empty-gallery"><div><strong>Nothing framed just yet.</strong>Make a moment together, and it’ll be waiting here.</div></div>';return}grid.innerHTML=[...items].reverse().map(k=>`<article class="keepsake"><div class="keepsake-art" style="background-image:url('${k.image}')"><div class="keepsake-caption">${escapeHtml(k.caption)}</div></div><div class="keepsake-meta"><span>${k.name} · ${k.date}</span><span>✦ Keepsake</span></div></article>`).join('')}
25: function openModal(){if(!activeChar)activeChar=characters.find(c=>c.id==='mira');$('#modalTitle').textContent=`A moment with ${activeChar.name.split(' ')[0]}.`;$('#scenePrompt').value='';$('#artCaption').textContent='Your story, still unfolding…';$('#artCredit').textContent=`WITH ${activeChar.name.toUpperCase()}`;$('#imageModal').classList.remove('hidden');document.body.style.overflow='hidden';$('#scenePrompt').focus()}
26: function closeModal(){ $('#imageModal').classList.add('hidden');document.body.style.overflow=''}
27: function seededRandom(seed){let x=seed||12345;return()=>{x=(x*1664525+1013904223)>>>0;return x/4294967296}}
28: function makeArtwork(prompt,char){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=900;canvas.height=1000;let seed=[...prompt+char.id].reduce((a,c)=>a+c.charCodeAt(0),0),rand=seededRandom(seed),colors=char.id==='mira'?['#342538','#84536c','#e6a591','#f5d6bd']:char.id==='rowan'?['#243844','#536e73','#c38d72','#e6c6a2']:['#202942','#4b5c82','#cc8193','#e6b78a'];const sky=ctx.createLinearGradient(0,0,0,1000);sky.addColorStop(0,colors[0]);sky.addColorStop(.52,colors[1]);sky.addColorStop(1,colors[2]);ctx.fillStyle=sky;ctx.fillRect(0,0,900,1000);
29: let glow=ctx.createRadialGradient(650,300,10,650,300,470);glow.addColorStop(0,colors[3]+'bb');glow.addColorStop(1,colors[3]+'00');ctx.fillStyle=glow;ctx.fillRect(0,0,900,850);
30: // softly textured twilight sky
31: for(let i=0;i<190;i++){const x=rand()*900,y=rand()*600,r=rand()*2.2+.4;ctx.fillStyle=`rgba(255,235,220,${rand()*.45})`;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
32: const promptLow=prompt.toLowerCase(),isCity=/cafe|book|city|rain|rooftop|street/.test(promptLow),water=/sea|coast|beach|water/.test(promptLow),night=/star|night|moon/.test(promptLow);if(night||char.id==='sol'){ctx.beginPath();ctx.arc(670,260,82,0,Math.PI*2);ctx.fillStyle='#ffe2bd';ctx.shadowColor='#ffe2bd99';ctx.shadowBlur=45;ctx.fill();ctx.shadowBlur=0}
