const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
(async () => {
  const config = JSON.parse(readFileSync(process.env.HOME + '/.local/share/omgithub-playwright/linux.json', 'utf8'));
  const browser = await chromium.launch({ ...config.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('response', r => { if (r.status() >= 400 && new URL(r.url()).origin === 'http://localhost:3002') errors.push(r.status() + ' ' + r.url()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.locator('[data-view="gallery"]').click();
  await page.locator('#galleryGenerate').click();
  await page.locator('#scenePrompt').fill('A rainy-night bookstore, sharing a secret smile');
  await page.locator('#generateImage').click();
  await page.waitForFunction(() => document.querySelectorAll('#galleryGrid .keepsake').length === 1, { timeout: 10000 });
  await page.screenshot({ path: '/tmp/opencode/afterglow-keepsakes.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ title: await page.title(), galleryItems: await page.locator('#galleryGrid .keepsake').count(), caption: await page.locator('.keepsake-caption').innerText(), viewport: page.viewportSize(), errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
